window.kbPageData["views/entry/k-26362ad0ed6d17bc"] = {"key":"entry/k-26362ad0ed6d17bc","state":{"route":"entry/k-26362ad0ed6d17bc"},"node":{"id":"k-26362ad0ed6d17bc","mode":"k","title":"总论 · 哲学的基本问题","type":"原理与机制","domain":"哲学","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["原理与机制"],"出处性质":["理论手册"],"学科":["哲学"],"来源主题":["马克思主义哲学"],"资料类别":["非时政"]},"seeAlso":["k-497a37f7846de49c"],"directorySummary":"二、哲学的基本问题\n哲学的基本问题是思维和存在的关系问题。这个问题包括以下两个方面：\n第一方面：思维和存在何者是本原的问题，即何者是第一性的问题。对这个问题的不同\n回答，是划分唯物主义和唯心主义两大派别的唯一标准。\n唯物主义认为世界的本原是物质，物质第一性；唯心主义认为世界的本原是意识，意识\n第一性…","sources":[{"id":"5cec7f58a6753672","label":"总论 · 哲学的基本问题","topic":"马克思主义哲学","category":"非时政","text":"二、哲学的基本问题\n哲学的基本问题是思维和存在的关系问题。这个问题包括以下两个方面：\n第一方面：思维和存在何者是本原的问题，即何者是第一性的问题。对这个问题的不同\n回答，是划分唯物主义和唯心主义两大派别的唯一标准。\n唯物主义认为世界的本原是物质，物质第一性；唯心主义认为世界的本原是意识，意识\n第一性。\n第二方面：思维和存在有无同一性的问题，即人的思维能否正确认识存在的问题。根据\n对这个问题的不同回答，可以将哲学划分为可知论和不可知论。\n（粉笔敲黑板：本考点重点在于区分唯物主义与唯心主义，考试极有可能给一段事例、\n讲话或者古语，要求辨析体现的是唯物主义还是唯心主义）","source":{"doc":"3ccc56f4000d1642c2d1","first":1,"last":1,"page":1,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{},"terms":{"k-497a37f7846de49c":{"id":"k-497a37f7846de49c","mode":"k","type":"概念与词义","title":"可知论与不可知论","qs":[],"count":0}},"references":{},"topics":[],"units":{"k-26362ad0ed6d17bc":[]}};
